<script setup>
import { ref, watch } from 'vue'
import { useWorkspace } from '../stores/workspace'
import { api } from '../services/api'
import AIServiceSettings from '../components/AIServiceSettings.vue'
import BedConfiguration from '../components/BedConfiguration.vue'
const s=useWorkspace(), section=ref('ward'), form=ref({}), revision=ref(0), bedConfig=ref(null), passwords=ref({old_password:'',new_password:''}), log=ref(null)
const sections=[['ward','病区基础设置','病区、床位信息及大组设置'],['allocation','床位分配规则','分管数量、组合条件与负荷'],['ai','AI服务配置','服务商、模型与安全密钥'],['notifications','数据与通知设置','发布通知与统计来源'],['account','账号与个人设置','账号角色与密码管理'],['audit','安全与操作日志','发布版本及变更记录']]
function reset(){form.value=JSON.parse(JSON.stringify(s.data.group.rules));revision.value=s.data.group.revision}
function choose(key){section.value=key;reset()}
async function save(keys){const r=await s.run(()=>api('settings/','PATCH',{...s.groupPayload(),revision:revision.value,rules:Object.fromEntries(keys.map(k=>[k,form.value[k]]))}),'配置已保存');if(r){reset();bedConfig.value?.refreshRevision()}}
async function password(){const r=await s.run(()=>api('auth/password/','POST',passwords.value),'密码已修改');if(r)passwords.value={old_password:'',new_password:''}}
reset()
watch(()=>s.data.group.id,()=>{log.value=null;reset()})
</script>
<template><div class="page-heading"><div><h1>系统设置</h1><p>{{s.data.group.name}} · 基础配置与系统管理</p></div></div><div class="settings-layout"><nav class="settings-nav"><button v-for="[key,label,hint] in sections" :key="key" :class="{active:section===key}" @click="choose(key)"><b>{{label}}</b><small>{{hint}}</small></button></nav><div>
<section v-if="section==='ward'" class="card"><div class="card-title"><h2>病区基础设置</h2><el-button type="primary" :disabled="!s.canEdit" :loading="s.busy" @click="save(s.user.role==='system_admin'?['ward_name','ward_code']:['ward_name'])">保存病区信息</el-button></div><el-form label-position="top" :disabled="!s.canEdit"><div class="form-grid"><el-form-item label="病区名称"><el-input v-model="form.ward_name"/></el-form-item><el-form-item label="病区编号（全局管理）"><el-input v-model="form.ward_code" :disabled="s.user.role!=='system_admin'"/></el-form-item><el-form-item label="所属大组"><el-input :model-value="s.data.group.name" disabled/></el-form-item></div></el-form><BedConfiguration ref="bedConfig" :key="s.data.group.id" @saved="reset"/></section>
<section v-if="section==='allocation'" class="card"><div class="card-title"><h2>床位分配规则</h2><el-button type="primary" :disabled="!s.canEdit" :loading="s.busy" @click="save(['normal_beds','max_beds','max_load','high_min_years','triple_min_years','allow_three_light','allow_two_light_medium'])">保存规则</el-button></div><el-alert title="数值为研究演示配置，需医院或科室确认；资质要求与最多3床限制始终在后端执行。" type="warning" :closable="false"/><el-form label-width="210px" :disabled="!s.canEdit"><el-form-item label="常规分管患者数"><el-input-number :model-value="2" disabled/><span class="muted small">　常规固定为2床</span></el-form-item><el-form-item label="每名护士最多患者数"><el-input-number v-model="form.max_beds" :min="2" :max="3"/></el-form-item><el-form-item label="总护理负荷上限"><el-input-number v-model="form.max_load" :min="1" :max="12"/></el-form-item><el-form-item label="高负荷患者最低ICU年资"><el-input-number v-model="form.high_min_years" :min="0" :max="60"/></el-form-item><el-form-item label="3床组合最低ICU年资"><el-input-number v-model="form.triple_min_years" :min="0" :max="60"/></el-form-item><el-form-item label="允许的3床组合"><div><el-checkbox v-model="form.allow_three_light">3名较轻患者</el-checkbox><br/><el-checkbox v-model="form.allow_two_light_medium">2名较轻＋1名稍重</el-checkbox></div></el-form-item></el-form><p class="muted small">演示负荷权重：较轻1、稍重2、高负荷4。特殊治疗须具备对应有效独立资质。只参加培训的技能标签不作为独立资质。</p></section>
<AIServiceSettings v-if="section==='ai'"/>
<section v-if="section==='notifications'" class="card"><div class="card-title"><h2>数据与通知设置</h2><el-button type="primary" :disabled="!s.canEdit" @click="save(['notify_publications'])">保存</el-button></div><el-switch v-model="form.notify_publications" active-text="排班与床位分配发布后发送站内通知" :disabled="!s.canEdit"/><div class="role-info section-gap"><h3>数据同步与统计来源</h3><p>保存后重新读取后端数据，页面每15秒刷新工作台。分床卡片和护士分管床位从同一份责任关系计算。</p><p>工作量只聚合正式发布记录；未连接考勤、HIS或EMR。发布修订以最新有效版本计算，历史版本保留。</p><p>失败反馈保留在操作窗口中；发生版本冲突请刷新并核对后重试。</p></div></section>
<section v-if="section==='account'" class="card"><h2>账号与个人设置</h2><dl class="detail-list"><dt>账号</dt><dd>{{s.user.username}}</dd><dt>昵称</dt><dd>{{s.user.name}}</dd><dt>角色</dt><dd>{{s.user.label}}</dd><dt>权限范围</dt><dd>{{s.user.role==='head_nurse'?'跨组只读':s.user.role==='system_admin'?'全局系统管理':s.data.group.name}}</dd></dl><el-divider/><h3>修改登录密码</h3><el-form label-position="top" style="max-width:440px"><el-form-item label="原密码"><el-input v-model="passwords.old_password" type="password" show-password autocomplete="current-password"/></el-form-item><el-form-item label="新密码"><el-input v-model="passwords.new_password" type="password" show-password autocomplete="new-password"/></el-form-item><el-button type="primary" :loading="s.busy" @click="password">更新密码</el-button></el-form><a v-if="s.user.role==='system_admin'" href="http://127.0.0.1:8000/admin/scheduling/accountprofile/" target="_blank" class="section-gap" style="display:inline-block">前往 SimpleUI 管理账号权限 ↗</a></section>
<section v-if="section==='audit'" class="card"><h2>安全与操作日志</h2><el-alert title="正式发布版本只读。日志记录操作人、时间、版本与变更；患者病历全文及API密钥不写入通用日志。" type="info" :closable="false"/><el-table :data="s.data.logs"><el-table-column label="时间" min-width="160"><template #default="{row}">{{new Date(row.created_at).toLocaleString('zh-CN')}}</template></el-table-column><el-table-column prop="actor__username" label="操作人"/><el-table-column prop="action" label="操作内容"/><el-table-column label="详情" width="90"><template #default="{row}"><el-button link type="primary" @click="log=row">查看</el-button></template></el-table-column></el-table></section>
</div></div><el-dialog :model-value="!!log" title="操作记录详情" width="660px" @close="log=null"><pre style="white-space:pre-wrap;word-break:break-all;font-size:12px">{{log?JSON.stringify(log.details,null,2):''}}</pre></el-dialog></template>
